@@ -47,14 +47,30 @@
  * falschen, jetzt fremden api.js-Präfix (404 bei jedem Tick, Senden-Button
  * blieb tot).
  *
+ * F26 WS-2b: ein persistierter Jarvis-Eintrag mit art 'auftrag_vorschlag' oder 'aktion' bekommt
+ * einen Bedienknopf (renderAktionsBlock), der an bestehende F22-/F23-Endpunkte anschließt, statt
+ * eine eigene Vorschlags-/Freigabe-Ansicht zu bauen: "Auftrag anlegen" legt über legeAuftragAn
+ * einen Auftrag an, routet ihn sofort (routeAuftrag, F22-Pfad) und navigiert zur bestehenden
+ * Workflow-Detailansicht (`#/workflows/<id>`, views/workflows.js — dieselbe Freigabe-/Abnahme-UI,
+ * die auch F22/F23 bedienen, WIEDERVERWENDET statt dupliziert; workflowId ist deterministisch
+ * `router-<auftragId>`, dasselbe Muster wie views/workboard.js und views/capabilities.js). "Öffnen"
+ * navigiert clientseitig zu aktion.ziel (bestehendes Hash-Routing). "Anpassung anfordern"
+ * (aktion.typ 'anpassen', bezug.auftrag_id — vom Schema seit WS-2b erzwungen) löst den zu
+ * bezug.auftrag_id gehörenden, NICHT GESTOPPTEN Workflow über GET /api/workflows auf und ruft
+ * POST /api/workflows/<id>/abnahme mit {ergebnis:'ANPASSUNG_ANGEFORDERT', begruendung:<Chat-
+ * Nachricht>} — derselbe F23-ADJUST-Pfad wie der Abnahme-Block in views/workflows.js, hier nur
+ * über den Chat statt über einen Klick in der Workflow-Ansicht ausgelöst. Vorfilter-/lokale
+ * Fehleinträge tragen nie ein solches ergebnis (loeseVorfilterAuf liefert nur art 'antwort') —
+ * der Aktionsblock erscheint deshalb ausschließlich an persistierten Jarvis-Einträgen.
+ *
  * Wird aufgerufen von:
  * - public/leitstand/app.js (initChatView beim Bootstrap)
  */

-import { holeChatVerlauf, holeLaufDetail, sendeChatNachricht } from '../api.js'
+import { holeChatVerlauf, holeLaufDetail, holeWorkflows, legeAuftragAn, routeAuftrag, sendeAbnahme, sendeChatNachricht } from '../api.js'
 import { escapeHtml } from '../render.js'
 import { abonniereProjektWechsel } from '../projekt-kontext.js'
-import { registriere } from '../router.js'
+import { navigiere, registriere } from '../router.js'
