@@ -76,17 +92,51 @@ function antwortText(antwort) {
   return antwort.antwort
 }

-/** Baut die Anzeigeliste: persistierter Verlauf (bereits serverseitig aufsteigend sortiert) gefolgt von lokalen Einträgen (Push-Reihenfolge) und einem etwaigen ausstehenden Lauf zuletzt — beide Quellen entstehen immer chronologisch NACH dem zuletzt geladenen persistierten Stand, eine erneute Sortierung ist deshalb nicht nötig. */
+/** Baut die Anzeigeliste: persistierter Verlauf (bereits serverseitig aufsteigend sortiert) gefolgt von lokalen Einträgen (Push-Reihenfolge) und einem etwaigen ausstehenden Lauf zuletzt — beide Quellen entstehen immer chronologisch NACH dem zuletzt geladenen persistierten Stand, eine erneute Sortierung ist deshalb nicht nötig. `ergebnis` trägt bei jarvis-Einträgen das volle JarvisErgebnis (für renderAktionsBlock, WS-2b) — Vorfilter-/Fehler-/ausstehend-Einträge tragen dort null (loeseVorfilterAuf liefert nie auftrag_vorschlag/aktion, ein Fehlereintrag hat keine gültige Ergebnisform). */
 function baueAnzeigeListe() {
-  const liste = [...persistierterVerlauf.map((e) => ({ nachricht: e.nachricht, antwortText: antwortText(e.jarvisAntwort), quelle: 'jarvis' })), ...lokaleEintraege]
+  const liste = [...persistierterVerlauf.map((e) => ({ nachricht: e.nachricht, antwortText: antwortText(e.jarvisAntwort), quelle: 'jarvis', ergebnis: e.jarvisAntwort })), ...lokaleEintraege]
   if (ausstehenderLauf !== null) {
-    liste.push({ nachricht: ausstehenderLauf.nachricht, antwortText: null, quelle: 'ausstehend' })
+    liste.push({ nachricht: ausstehenderLauf.nachricht, antwortText: null, quelle: 'ausstehend', ergebnis: null })
   }
   return liste
 }

 const QUELLE_LABEL = { jarvis: 'Jarvis', vorfilter: 'Vorfilter (lokal)', fehler: 'Fehler', ausstehend: 'Lauf gestartet' }

+/**
+ * F26 WS-2b: der Bedienknopf zu EINEM persistierten Jarvis-Ergebnis, wenn es eine Aktion trägt.
+ * Reine Anzeigeentscheidung nach ergebnis.art/aktion.typ (D5) — ausgeführt wird nichts hier, nur
+ * das data-*-Rohmaterial für initChatAktionen()s Klick-Delegation aufbereitet (escapeHtml auch für
+ * Attribute: der Browser dekodiert HTML-Entities beim Lesen aus .dataset zurück in den Originaltext).
+ * @param eintrag - ein Eintrag aus baueAnzeigeListe ({ nachricht, ergebnis, … })
+ * @returns HTML-Block, oder '' ohne passende Aktion
+ */
+function renderAktionsBlock(eintrag) {
+  const ergebnis = eintrag.ergebnis
+  if (ergebnis === null || ergebnis === undefined) return ''
+
+  if (ergebnis.art === 'auftrag_vorschlag' && ergebnis.auftrag) {
+    return `<div class="chat-aktion">
+      <button class="chat-anlegen" data-titel="${escapeHtml(ergebnis.auftrag.titel)}" data-text="${escapeHtml(ergebnis.auftrag.text)}">Auftrag anlegen</button>
+      <span class="chat-aktion-meldung" hidden></span>
+    </div>`
+  }
+  if (ergebnis.art === 'aktion' && ergebnis.aktion?.typ === 'oeffnen') {
+    return `<div class="chat-aktion"><button class="chat-oeffnen" data-ziel="${escapeHtml(ergebnis.aktion.ziel)}">Öffnen</button></div>`
+  }
+  // Schema/Validator erzwingen bezug.auftrag_id bei aktion.typ 'anpassen' (F26 WS-2b) — die
+  // optionale Verkettung unten ist trotzdem kein Vertrauensbruch: ein ÄLTERER, vor WS-2b real
+  // geschriebener Lineage-Eintrag könnte theoretisch diese Form nicht tragen, und ein Knopf ohne
+  // gültige auftrag_id wäre nicht bedienbar.
+  if (ergebnis.art === 'aktion' && ergebnis.aktion?.typ === 'anpassen' && ergebnis.bezug?.auftrag_id) {
+    return `<div class="chat-aktion">
+      <button class="chat-anpassen" data-auftrag-id="${escapeHtml(ergebnis.bezug.auftrag_id)}" data-nachricht="${escapeHtml(eintrag.nachricht)}">Anpassung anfordern</button>
+      <span class="chat-aktion-meldung" hidden></span>
+    </div>`
+  }
+  return ''
+}
+
 function renderEintrag(eintrag) {
   const quelleLabel = escapeHtml(QUELLE_LABEL[eintrag.quelle] ?? eintrag.quelle)
   const antwortHtml =
@@ -97,6 +147,7 @@ function renderEintrag(eintrag) {
     <p class="chat-nachricht"><strong>Du:</strong> ${escapeHtml(eintrag.nachricht)}</p>
     <p class="chat-quelle">${quelleLabel}</p>
     ${antwortHtml}
+    ${renderAktionsBlock(eintrag)}
   </div>`
 }

@@ -112,6 +163,126 @@ function zeigeChatFehler(text) {
   anzeige.hidden = text === ''
 }

+// ─── Aktionen (F26 WS-2b): Auftrag anlegen+routen, Öffnen, Anpassung anfordern ──────────────
+
+/** @param button - der Knopf, dessen Geschwister-Meldungselement (.chat-aktion-meldung) aktualisiert wird @param text - anzuzeigender Text @param art - 'fehler' (Vorgabe), 'hinweis' oder 'erfolg' */
+function zeigeAktionsMeldung(button, text, art = 'fehler') {
+  const meldung = button.parentElement.querySelector('.chat-aktion-meldung')
+  if (meldung === null) return
+  meldung.className = `chat-aktion-meldung ${art}`
+  meldung.textContent = text
+  meldung.hidden = false
+}
+
+/**
+ * "Auftrag anlegen" an einem auftrag_vorschlag-Eintrag: legt den Auftrag an (legeAuftragAn, F22-
+ * Formfeld auftragstext aus ergebnis.auftrag.text), routet ihn sofort (routeAuftrag, F22-Pfad) und
+ * navigiert danach zur bestehenden Workflow-Detailansicht — dieselbe Freigabe-/Abnahme-Bedienung
+ * wie an jedem anderen Workflow (views/workflows.js), WIEDERVERWENDET statt dupliziert.
+ * workflowId ist deterministisch `router-<auftragId>` (Muster views/workboard.js Zeile ~377,
+ * views/capabilities.js Zeile ~426 — derselbe Client-seitige Ableitungsweg, kein dritter hier neu
+ * erfunden). Der Router-Lauf selbst ist asynchron (202 + laufId); die Ziel-View findet den
+ * Workflow ggf. erst nach ein paar Poll-Ticks — dafür sorgt bereits deren eigener
+ * Detail-Auffrischer (kein neuer Poll hier nötig).
+ * @param button - der geklickte .chat-anlegen-Knopf
+ */
+async function fuehreAnlegenAus(button) {
+  button.disabled = true
+  zeigeAktionsMeldung(button, 'Auftrag wird angelegt…', 'hinweis')
+  try {
+    const auftragAntwort = await legeAuftragAn({ titel: button.dataset.titel, auftragstext: button.dataset.text })
+    const auftragInhalt = await auftragAntwort.json().catch(() => ({}))
+    if (!auftragAntwort.ok) {
+      zeigeAktionsMeldung(button, `Auftrag konnte nicht angelegt werden: ${auftragAntwort.status} ${auftragInhalt.grund ?? ''}`.trim())
+      button.disabled = false
+      return
+    }
+    const auftragId = auftragInhalt.auftragId
+    zeigeAktionsMeldung(button, 'Wird geroutet…', 'hinweis')
+    const routeAntwort = await routeAuftrag(auftragId)
+    if (routeAntwort.status !== 202) {
+      const routeInhalt = await routeAntwort.json().catch(() => ({}))
+      zeigeAktionsMeldung(button, `${routeAntwort.status}: ${routeInhalt.grund ?? 'Routen fehlgeschlagen'}`)
+      button.disabled = false
+      return
+    }
+    navigiere(`#/workflows/${encodeURIComponent(`router-${auftragId}`)}`)
+  } catch (fehler) {
+    zeigeAktionsMeldung(button, `Anfrage fehlgeschlagen: ${fehler.message}`)
+    button.disabled = false
+  }
+}
+
+/** "Öffnen" an einem aktion.typ 'oeffnen'-Eintrag: rein clientseitige Navigation über das bestehende Hash-Routing — ziel ohne führendes '#' wird als Routenname interpretiert (Jarvis liefert laut Schema "eine Auftrags-ID oder ein Leitstand-Routenname", kein freier Pfad). @param button - der geklickte .chat-oeffnen-Knopf */
+function fuehreOeffnenAus(button) {
+  const ziel = button.dataset.ziel
+  navigiere(ziel.startsWith('#') ? ziel : `#/${ziel.replace(/^\/+/, '')}`)
+}
+
+/**
+ * "Anpassung anfordern" an einem aktion.typ 'anpassen'-Eintrag (bezug.auftrag_id vom Schema
+ * erzwungen, F26 WS-2b): löst den zugehörigen, NICHT GESTOPPTEN Workflow über GET /api/workflows
+ * auf (Projektion, Muster GET /api/workitems' workitem_referenz-Auflösung — kein Rückgriff auf die
+ * interne `router-<auftragId>`-Namenskonvention, die woanders für einen FRISCH gerouteten Auftrag
+ * gilt, hier aber ein bereits gelaufener, möglicherweise über einen früheren ADJUST-Zyklus
+ * fortgeschriebener Workflow sein kann) und fordert dort dieselbe Anpassung an, die der
+ * Abnahme-Block in views/workflows.js über den 'ANPASSUNG_ANGEFORDERT'-Knopf auslöst (F23-ADJUST-
+ * Pfad, POST /api/workflows/<id>/abnahme) — kein neuer Workflow, derselbe setzt Ausführungs- und
+ * Review-Schritt zurück. Die ursprüngliche Chat-Nachricht wird wörtlich als Begründung übergeben
+ * (Pflichtfeld des Endpunkts).
+ * @param button - der geklickte .chat-anpassen-Knopf
+ */
+async function fuehreAnpassenAus(button) {
+  button.disabled = true
+  zeigeAktionsMeldung(button, 'Löse zugehörigen Workflow auf…', 'hinweis')
+  const auftragId = button.dataset.auftragId
+  try {
+    const workflows = await holeWorkflows()
+    const treffer = workflows.filter((w) => w.auftragId === auftragId && w.status !== 'GESTOPPT')
+    if (treffer.length === 0) {
+      zeigeAktionsMeldung(button, `Kein offener Workflow zu Auftrag '${auftragId}' gefunden.`)
+      button.disabled = false
+      return
+    }
+    if (treffer.length > 1) {
+      zeigeAktionsMeldung(button, `Mehrdeutig: ${treffer.length} offene Workflows zu Auftrag '${auftragId}' gefunden — Anpassung über die Workflow-Ansicht anfordern.`)
+      button.disabled = false
+      return
+    }
+    const workflowId = treffer[0].workflowId
+    zeigeAktionsMeldung(button, 'Anpassung wird angefordert…', 'hinweis')
+    const abnahmeAntwort = await sendeAbnahme(workflowId, { ergebnis: 'ANPASSUNG_ANGEFORDERT', begruendung: button.dataset.nachricht })
+    const abnahmeInhalt = await abnahmeAntwort.json().catch(() => ({}))
+    if (!abnahmeAntwort.ok) {
+      zeigeAktionsMeldung(button, `${abnahmeAntwort.status}: ${abnahmeInhalt.grund ?? 'unbekannter Fehler'}`)
+      button.disabled = false
+      return
+    }
+    navigiere(`#/workflows/${encodeURIComponent(workflowId)}`)
+  } catch (fehler) {
+    zeigeAktionsMeldung(button, `Anfrage fehlgeschlagen: ${fehler.message}`)
+    button.disabled = false
+  }
+}
+
+/** Klick-Delegation der drei Aktionsknöpfe — ein Listener auf dem Container statt drei je Eintrag (Muster initWorkflowBedienung, views/workflows.js), weil renderVerlauf() den Container bei jedem Tick komplett ersetzt. */
+function initChatAktionen() {
+  document.getElementById('chat-verlauf').addEventListener('click', (ereignis) => {
+    const anlegenButton = ereignis.target.closest('.chat-anlegen')
+    if (anlegenButton) {
+      void fuehreAnlegenAus(anlegenButton)
+      return
+    }
+    const oeffnenButton = ereignis.target.closest('.chat-oeffnen')
+    if (oeffnenButton) {
+      fuehreOeffnenAus(oeffnenButton)
+      return
+    }
+    const anpassenButton = ereignis.target.closest('.chat-anpassen')
+    if (anpassenButton) void fuehreAnpassenAus(anpassenButton)
+  })
+}
+
 /** Setzt Eingabefeld/Sende-Button in den Wartezustand — solange ein Vorfilter-Abruf läuft ODER ein Jarvis-Lauf aussteht (D13 lässt ohnehin nur einen Lauf zu). */
 function setzeSendenSperre(gesperrt) {
   document.getElementById('chat-senden').disabled = gesperrt
@@ -170,7 +341,7 @@ async function pruefeAusstehendenLauf() {
     const geladen = await ladeVerlauf()
     if (!geladen) return
   } else {
-    lokaleEintraege.push({ nachricht, antwortText: beschreibeNichtErfolgreichesEnde(laufStatus), quelle: 'fehler' })
+    lokaleEintraege.push({ nachricht, antwortText: beschreibeNichtErfolgreichesEnde(laufStatus), quelle: 'fehler', ergebnis: null })
